    @staticmethod
    def digitar(texto, cor=Fore.YELLOW, delay=0.012):
        for ch in texto:
            print(cor + ch, end='', flush=True)
            if ch in '.!?':
                time.sleep(0.18)
            elif ch == ',':
                time.sleep(0.08)
            else:
                time.sleep(delay)
        print()

    @staticmethod
    def separador(titulo="", cor=Fore.RED):
        w = 64
        if titulo:
            pad = (w - len(titulo) - 2) // 2
            print(cor + "─" * pad + f" {titulo} " + "─" * pad)
        else:
            print(cor + "─" * w)

