            print(f"{Fore.GREEN}[OK] {len(conteudo)} chars")

            # Extrai técnicas via GPT
            prompt = (
                f"Conteúdo da documentação do Claude/Anthropic:\n{conteudo[:2000]}\n\n"
                f"Extraia as técnicas de prompt engineering mais importantes para:\n"
