            "no magi", "no seu código", "em você", "em si mesmo",
            "adiciona ao magi", "adicione ao magi", "corrige o magi",
            "melhora o magi", "melhore o magi", "modifica o magi",
            "adiciona um comando", "adicione um comando",
            "novo comando", "nova feature", "nova função no magi",
            "corrija você", "se corrija", "evolua", "evoluir",
        ]
        return any(g in q for g in gatilhos)

