        duracao = datetime.now() - self.sessao_inicio
        mins, secs = divmod(int(duracao.total_seconds()), 60)
        print()
        MAGIInterface.separador("ENCERRANDO SESSÃO MAGI", Fore.RED)
        print(f"{Fore.CYAN}  Duração  : {mins}m {secs}s")
